def minimum_path_sum(grid):
    costs = [float("inf")] * len(grid[0])
    costs[0] = 0
    for row in grid:
        for col, value in enumerate(row):
            costs[col] = value + min(costs[col], costs[col - 1] if col else float("inf"))
    return costs[-1]

